}

fn git_commit_all(root: &Path, message: &str) {
    assert!(Command::new("git")
        .args(["add", "-A"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
    assert!(Command::new("git")
        .args(["commit", "-q", "-m", message])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
}

fn run_callisto(root: &Path, args: &[&str]) -> serde_json::Value {
